import{_ as d,a0 as o,w as r,s as p,I as s,x as i,a1 as l,A as a,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 上操作目錄 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上操作目錄 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上操作目錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上操作目錄 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180516 Manipulating Directories in Linux","title":"在 Linux 上操作目錄","tag":"201809","desc":""},"relativePath":"201809/20180516 Manipulating Directories in Linux.md","filePath":"[post].md"}'),u={name:"201809/20180516 Manipulating Directories in Linux.md"};function g(h,e,k,c,m,b){const t=o("Link");return r(),p("div",null,[e[34]||(e[34]=s("h1",{id:"在-linux-上操作目錄",tabindex:"-1"},[i("在 Linux 上操作目錄 "),s("a",{class:"header-anchor",href:"#在-linux-上操作目錄","aria-label":"Permalink to “在 Linux 上操作目錄”"},"​")],-1)),e[35]||(e[35]=s("p",null,[s("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/branches-238379_1920_0.jpg?itok=2PlNpsVu",alt:""})],-1)),e[36]||(e[36]=s("blockquote",null,[s("p",null,"讓我們繼續學習一下 Linux 文件系統的樹形結構，並展示一下如何在其中創建你的目錄。")],-1)),s("p",null,[e[1]||(e[1]=i("如果你不熟悉本系列（以及 Linux），",-1)),l(t,{href:"https://linux.cn/article-9798-1.html"},{default:a(()=>[...e[0]||(e[0]=[i("請查看我們的第一部分",-1)])]),_:1}),e[2]||(e[2]=i("。在那篇文章中，我們貫穿了 Linux 文件系統的樹狀結構（或者更確切地説是",-1)),e[3]||(e[3]=s("ruby",null,[i("文件層次結構標準"),s("rt",null,"File Hierarchy Standard")],-1)),e[4]||(e[4]=i("，FHS）。我建議你仔細閲讀，確保你理解自己能安全的做哪些操作。因為這一次，我將向你展示目錄操作的魅力。",-1))]),e[37]||(e[37]=n(`<h3 id="新建目錄" tabindex="-1">新建目錄 <a class="header-anchor" href="#新建目錄" aria-label="Permalink to “新建目錄”">​</a></h3><p>在破壞之前，先讓我們來創建。首先，打開一個終端窗口並使用命令 <code>mkdir</code> 創建一個新目錄，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir &lt;directoryname&gt;</span></span></code></pre></div><p>如果你只輸入了目錄名稱，該目錄將顯示在您當前所在目錄中。如果你剛剛打開一個終端，你當前位置為你的家目錄。在這個例子中，我們展示了將要創建的目錄與你當前所處位置的關係：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd # 告知你當前所在位置（參見第一部分）</span></span>
<span class="line"><span>/home/&lt;username&gt;</span></span>
<span class="line"><span>$ mkdir newdirectory # 創建 /home/&lt;username&gt;/newdirectory</span></span></code></pre></div><p>（注：你不用輸入 <code>＃</code> 後面的文本。<code>#</code> 後面的文本為註釋內容，用於解釋發生了什麼。它會被 shell 忽略，不會被執行）。</p><p>你可以在當前位置中已經存在的某個目錄下創建新的目錄，方法是在命令列中指定它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir Documents/Letters</span></span></code></pre></div><p>這將在 <code>Documents</code> 目錄中創建 <code>Letters</code> 目錄。</p><p>你還可以在路徑中使用 <code>..</code> 在當前目錄的上一級目錄中創建目錄。假設你進入剛剛創建的 <code>Documents/Letters/</code> 目錄，並且想要創建<code>Documents/Memos/</code> 目錄。你可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd Documents/Letters # 進入到你剛剛創建的 Letters/ 目錄</span></span>
<span class="line"><span>mkdir ../Memos</span></span></code></pre></div><p>同樣，以上所有內容都是相對於你當前的位置做的。這就是使用了相對路徑。</p><p>你還可以使用目錄的絕對路徑：這意味着告訴 <code>mkdir</code> 命令將目錄放在和根目錄（<code>/</code>）有關的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir /home/&lt;username&gt;/Documents/Letters</span></span></code></pre></div><p>在上面的命令中將 <code>&lt;username&gt;</code> 更改為你的用户名，這相當於從你的主目錄執行 <code>mkdir Documents/Letters</code>，通過使用絕對路徑你可以在目錄樹中的任何位置完成這項工作。</p><p>無論你使用相對路徑還是絕對路徑，只要命令成功執行，<code>mkdir</code> 將靜默的創建新目錄，而沒有任何明顯的反饋。只有當遇到某種問題時，<code>mkdir</code>才會在你敲下回車鍵後打印一些反饋。</p><p>與大多數其他命令列工具一樣，<code>mkdir</code> 提供了幾個有趣的選項。 <code>-p</code> 選項特別有用，因為它允許你嵌套創建目錄，即使目錄不存在也可以。例如，要在 <code>Documents/</code> 中創建一個目錄存放寫給媽媽的信，你可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p Documents/Letters/Family/Mom</span></span></code></pre></div><p><code>mkdir</code> 會創建 <code>Mom/</code> 之上的整個目錄分支，並且也會創建 <code>Mom/</code> 目錄，無論其上的目錄在你敲入該命令時是否已經存在。</p><p>你也可以用空格來分隔目錄名，來同時創建幾個目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir Letters Memos Reports</span></span></code></pre></div><p>這將在當前目錄下創建目錄 <code>Letters</code>、<code>Memos</code> 和 <code>Reports</code>。</p><h3 id="目錄名中可怕的空格" tabindex="-1">目錄名中可怕的空格 <a class="header-anchor" href="#目錄名中可怕的空格" aria-label="Permalink to “目錄名中可怕的空格”">​</a></h3><p>……這帶來了目錄名稱中關於空格的棘手問題。你能在目錄名中使用空格嗎？是的你可以。那麼建議你使用空格嗎？不，絕對不建議。空格使一切變得更加複雜，並且可能是危險的操作。</p><p>假設您要創建一個名為 <code>letters mom/</code> 的目錄。如果你不知道如何更好處理，你可能會輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir letters mom</span></span></code></pre></div><p>但這是錯誤的！錯誤的！錯誤的！正如我們在上面介紹的，這將創建兩個目錄 <code>letters/</code> 和 <code>mom/</code>，而不是一個目錄 <code>letters mom/</code>。</p><p>得承認這是一個小麻煩：你所要做的就是刪除這兩個目錄並重新開始，這沒什麼大不了。</p>`,28)),s("p",null,[e[7]||(e[7]=i("可是等等！刪除目錄可是個危險的操作。想像一下，你使用圖形工具",-1)),l(t,{href:"https://userbase.kde.org/Dolphin"},{default:a(()=>[...e[5]||(e[5]=[i("Dolphin",-1)])]),_:1}),e[8]||(e[8]=i(" 或 ",-1)),l(t,{href:"https://projects-old.gnome.org/nautilus/screenshots.html"},{default:a(()=>[...e[6]||(e[6]=[i("Nautilus",-1)])]),_:1}),e[9]||(e[9]=i(" 創建了目錄 ",-1)),e[10]||(e[10]=s("code",null,"letters mom/",-1)),e[11]||(e[11]=i("。如果你突然決定從終端刪除目錄 ",-1)),e[12]||(e[12]=s("code",null,"letters mom",-1)),e[13]||(e[13]=i("，並且您在同一目錄下有另一個名為 ",-1)),e[14]||(e[14]=s("code",null,"letters",-1)),e[15]||(e[15]=i(" 的目錄，並且該目錄中包含重要的文檔，結果你為了刪除錯誤的目錄嘗試了以下操作：",-1))]),e[38]||(e[38]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rmdir letters mom</span></span></code></pre></div><p>你將會有刪除目錄 letters 的風險。這裏説“風險”，是因為幸運的是<code>rmdir</code> 這條用於刪除目錄的指令，有一個內置的安全措施，如果你試圖刪除一個非空目錄時，它會發出警告。</p><p>但是，下面這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -Rf letters mom</span></span></code></pre></div><p>（注：這是刪除目錄及其內容的一種非常標準的方式）將完全刪除 <code>letters/</code> 目錄，甚至永遠不會告訴你剛剛發生了什麼。）</p><p><code>rm</code> 命令用於刪除文件和目錄。當你將它與選項 <code>-R</code>（遞歸刪除）和 <code>-f</code>（強制刪除）一起使用時，它會深入到目錄及其子目錄中，刪除它們包含的所有文件，然後刪除子目錄本身，然後它將刪除所有頂層目錄中的文件，再然後是刪除目錄本身。</p><p><code>rm -Rf</code> 是你必須非常小心處理的命令。</p><p>我的建議是，你可以使用下劃線來代替空格，但如果你仍然堅持使用空格，有兩種方法可以使它們起作用。您可以使用單引號或雙引號，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir &#39;letters mom&#39;</span></span>
<span class="line"><span>mkdir &quot;letters dad&quot;</span></span></code></pre></div><p>或者，你可以轉義空格。有些字符對 shell 有特殊意義。正如你所見，空格用於在命令列上分隔選項和參數。 “分離選項和參數”屬於“特殊含義”範疇。當你想讓 shell 忽略一個字符的特殊含義時，你需要轉義，你可以在它前面放一個反斜槓（<code>\\</code>）如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir letters\\ mom</span></span>
<span class="line"><span>mkdir letter\\ dad</span></span></code></pre></div><p>還有其他特殊字符需要轉義，如撇號或單引號（<code>&#39;</code>），雙引號（<code>“</code>）和＆符號（<code>＆</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir mom\\ \\&amp;\\ dad\\&#39;s\\ letters</span></span></code></pre></div><p>我知道你在想什麼：如果反斜槓有一個特殊的含義（即告訴 shell 它必須轉義下一個字符），這也使它成為一個特殊的字符。然後，你將如何轉義轉義字符（<code>\\</code>）？</p><p>事實證明，你轉義任何其他特殊字符都是同樣的方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir special\\\\characters</span></span></code></pre></div><p>這將生成一個名為 <code>special\\characters/</code> 的目錄。</p><p>感覺困惑？當然。這就是為什麼你應該避免在目錄名中使用特殊字符，包括空格。</p><p>以防誤操作你可以參考下面這個記錄特殊字符的列表。（LCTT 譯註：此處原文鏈接丟失。）</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><ul><li>使用 <code>mkdir &lt;directory name&gt;</code> 創建新目錄。</li><li>使用 <code>rmdir &lt;directory name&gt;</code> 刪除目錄（僅在目錄為空時才有效）。</li><li>使用 <code>rm -Rf &lt;directory name&gt;</code> 來完全刪除目錄及其內容 —— 請務必謹慎使用。</li><li>使用相對路徑創建相對於當前目錄的目錄： <code>mkdir newdir</code>。</li><li>使用絕對路徑創建相對於根目錄(<code>/</code>)的目錄: <code>mkdir /home/&lt;username&gt;/newdir</code>。</li><li>使用 <code>..</code> 在當前目錄的上級目錄中創建目錄： <code>mkdir ../newdir</code>。</li><li>你可以通過在命令列上使用空格分隔目錄名來創建多個目錄: <code>mkdir onedir twodir threedir</code>。</li><li>同時創建多個目錄時，你可以混合使用相對路徑和絕對路徑: <code>mkdir onedir twodir /home/&lt;username&gt;/threedir</code>。</li><li>在目錄名稱中使用空格和特殊字符真的會讓你很頭疼，你最好不要那樣做。</li></ul><p>有關更多信息，您可以查看 <code>mkdir</code>、<code>rmdir</code> 和 <code>rm</code> 的手冊:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man mkdir</span></span>
<span class="line"><span>man rmdir</span></span>
<span class="line"><span>man rm</span></span></code></pre></div><p>要退出手冊頁，請按鍵盤 <code>q</code> 鍵。</p><h3 id="下次預告" tabindex="-1">下次預告 <a class="header-anchor" href="#下次預告" aria-label="Permalink to “下次預告”">​</a></h3><p>在下一部分中，你將學習如何創建、修改和刪除文件，以及你需要了解的有關權限和特權的所有信息!</p>`,26)),s("p",null,[e[17]||(e[17]=i("通過 Linux 基金會和 edX 免費提供的",-1)),l(t,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:a(()=>[...e[16]||(e[16]=[i("“Introduction to Linux”",-1)])]),_:1}),e[18]||(e[18]=i("課程瞭解有關Linux的更多信息。",-1))]),e[39]||(e[39]=s("hr",null,null,-1)),s("p",null,[e[20]||(e[20]=i("via: ",-1)),l(t,{href:"https://www.linux.com/blog/learn/2018/5/manipulating-directories-linux"},{default:a(()=>[...e[19]||(e[19]=[i("https://www.linux.com/blog/learn/2018/5/manipulating-directories-linux",-1)])]),_:1})]),s("p",null,[e[25]||(e[25]=i("作者：",-1)),l(t,{href:"https://www.linux.com/users/bro66"},{default:a(()=>[...e[21]||(e[21]=[i("Paul Brown",-1)])]),_:1}),e[26]||(e[26]=i(" 選題：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[22]||(e[22]=[i("lujun9972",-1)])]),_:1}),e[27]||(e[27]=i(" 譯者：",-1)),l(t,{href:"https://github.com/way-ww"},{default:a(()=>[...e[23]||(e[23]=[i("way-ww",-1)])]),_:1}),e[28]||(e[28]=i(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[24]||(e[24]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[31]||(e[31]=i("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[29]||(e[29]=[i("LCTT",-1)])]),_:1}),e[32]||(e[32]=i(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:a(()=>[...e[30]||(e[30]=[i("Linux中國",-1)])]),_:1}),e[33]||(e[33]=i(" 榮譽推出",-1))])])}const C=d(u,[["render",g]]);export{y as __pageData,C as default};
